raw_audio_harness:
#define _POSIX_C_SOURCE 200809L
#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <xmmintrin.h>
#include "onda_processor_abi.h"

static double now(void) {
  struct timespec t;
  clock_gettime(CLOCK_MONOTONIC, &t);
  return t.tv_sec + t.tv_nsec * 1e-9;
}

static int measure(int mode, int frames, int iterations, double *result) {
  _Alignas(64) float source[256], separate[256], expected[256];
  float gain = 0.75f;
  for (int i = 0; i < 256; ++i) source[i] = expected[i] = (float)i * 0.003f;
  memset(separate, 0, sizeof separate);
  float *destination = mode == 0 ? separate : source + (mode == 2 ? 1 : 0);
  const void *inputs[] = {source};
  void *outputs[] = {destination};
  if (onda_process(NULL, &gain, inputs, outputs, 0, frames,
                   ONDA_PROCESSOR_FULL_BLOCK, NULL, NULL, NULL, NULL, NULL)) return 1;
  if (mode == 2) {
    for (int i = 0; i < frames; ++i) expected[i + 1] = expected[i] * gain + 0.1f;
  } else {
    for (int i = 0; i < frames; ++i) expected[i] = expected[i] * gain + 0.1f;
  }
  for (int i = 0; i < frames; ++i) {
    if (memcmp(&destination[i], &expected[i + (mode == 2)], sizeof(float))) return 2;
  }
  for (int i = 0; i < 1000; ++i) {
    if (onda_process(NULL, &gain, inputs, outputs, 0, frames,
                     ONDA_PROCESSOR_FULL_BLOCK, NULL, NULL, NULL, NULL, NULL)) return 3;
  }
  double start = now();
  for (int i = 0; i < iterations; ++i) {
    if (onda_process(NULL, &gain, inputs, outputs, 0, frames,
                     ONDA_PROCESSOR_FULL_BLOCK, NULL, NULL, NULL, NULL, NULL)) return 4;
  }
  *result = (now() - start) * 1e9 / iterations / frames;
  if (!isfinite(destination[frames - 1])) return 5;
  return 0;
}

int main(void) {
  _mm_setcsr(_mm_getcsr() | (1u << 15) | (1u << 6));
  const int sizes[] = {1, 8, 32, 128};
  const char *names[] = {"disjoint", "in_place", "partial_overlap"};
  double measurements[4][3][7];
  for (int round = 0; round < 7; ++round) {
    for (int size = 0; size < 4; ++size) {
      for (int order = 0; order < 3; ++order) {
        int mode = (order + round) % 3;
        int status = measure(mode, sizes[size], 1000000, &measurements[size][mode][round]);
        if (status) { fprintf(stderr, "validation failed: %d\n", status); return status; }
      }
    }
  }
  printf("[\n");
  for (int size = 0; size < 4; ++size) for (int mode = 0; mode < 3; ++mode) {
    printf("{\"mode\":\"%s\",\"frames\":%d,\"rounds_ns_per_frame\":[", names[mode], sizes[size]);
    for (int round = 0; round < 7; ++round) printf("%s%.9f", round ? "," : "", measurements[size][mode][round]);
    printf("]}%s\n", size == 3 && mode == 2 ? "" : ",");
  }
  printf("]\n");
  return 0;
}
